#!/usr/bin/env python3
"""Parse a YAML file and extract nested columns as a Markdown table."""

import sys
import yaml


def flatten_dict(d, parent_key="", sep="."):
    """Flatten a nested dictionary using dot-separated keys."""
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep).items())
        elif isinstance(v, list):
            items.append((new_key, ", ".join(str(i) for i in v)))
        else:
            items.append((new_key, v))
    return dict(items)


def yaml_to_markdown(data):
    """Convert parsed YAML data to a Markdown table string."""
    if isinstance(data, dict) and not any(isinstance(v, (dict, list)) for v in data.values()):
        # Flat dict — single-row table
        headers = list(data.keys())
        row = [str(data[h]) for h in headers]
        return _build_table(headers, [row])

    if isinstance(data, list) and all(isinstance(item, dict) for item in data):
        # List of dicts — multi-row table
        flat_rows = [flatten_dict(item) for item in data]
        # Preserve column order from first row, append any extra keys
        headers = []
        seen = set()
        for row in flat_rows:
            for key in row:
                if key not in seen:
                    headers.append(key)
                    seen.add(key)
        rows = [[str(row.get(h, "")) for h in headers] for row in flat_rows]
        return _build_table(headers, rows)

    if isinstance(data, dict):
        # Nested dict — try to find a list inside
        for v in data.values():
            if isinstance(v, list) and all(isinstance(i, dict) for i in v):
                return yaml_to_markdown(v)
        # Fallback: flatten single dict
        flat = flatten_dict(data)
        return _build_table(list(flat.keys()), [list(map(str, flat.values()))])

    return f"```\n{data}\n```"


def _build_table(headers, rows):
    """Build a Markdown table from headers and rows."""
    col_widths = [len(h) for h in headers]
    for row in rows:
        for i, cell in enumerate(row):
            col_widths[i] = max(col_widths[i], len(cell))

    def fmt_row(cells):
        return "| " + " | ".join(c.ljust(w) for c, w in zip(cells, col_widths)) + " |"

    lines = [
        fmt_row(headers),
        "|" + "|".join("-" * (w + 2) for w in col_widths) + "|",
    ]
    for row in rows:
        lines.append(fmt_row(row))
    return "\n".join(lines)


def main():
    if len(sys.argv) < 2:
        print("Usage: yaml_to_md_table.py <file.yaml> [key]", file=sys.stderr)
        print("  If [key] is provided, only that nested key is used.", file=sys.stderr)
        sys.exit(1)

    path = sys.argv[1]
    with open(path) as f:
        data = yaml.safe_load(f)

    # Optional: drill into a specific top-level key
    if len(sys.argv) >= 3:
        key = sys.argv[2]
        if isinstance(data, dict) and key in data:
            data = data[key]
        else:
            print(f"Key '{key}' not found in YAML.", file=sys.stderr)
            sys.exit(1)

    print(yaml_to_markdown(data))


if __name__ == "__main__":
    main()
